/**
 * @brief Recognize a return path that forwards a call through a shared slot.
 *
 * @param fn Function containing the call.
 * @param source Block containing the call and its result store.
 * @param index Instruction index of the call.
 * @param result Call result ID to look for.
 * @return True if the successor returns the stored call result.
 */
// Match lowered conditionals that save a return value to a shared slot before
// returning it.
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Turn self calls in tail position into simultaneous parameter updates
// and a backedge.
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement. You can change IR if it improves the results/makes things
// more clear. Also try to split long files (300+) into smaller thematic ones,
// like optimizer was before" Changes: Recognize tail calls through an
// expression result slot and return join.
static bool returns_stored_call(const IrFunction* fn,
                                const IrBlock* source,
                                size_t index,
                                IrValueId result) {
  if (result == IR_INVALID_ID || index + 2 != source->instructions.count ||
      source->terminator.type != IR_TERMINATOR_JUMP)
    return false;

  const IrInstruction* store = &source->instructions.data[index + 1];
  const IrBlock* target =
      &fn->blocks.data[source->terminator.value.jump_target];

  if (store->type != IR_INST_STORE ||
      store->operands.store.source.type != IR_OP_VALUE ||
      store->operands.store.source.value.id != result ||
      target->instructions.count != 1 ||
      target->terminator.type != IR_TERMINATOR_RETURN)
    return false;

  const IrInstruction* load = &target->instructions.data[0];
  IrOperand returned = target->terminator.value.return_value;

  return load->type == IR_INST_LOAD &&
         load->operands.load.source == store->operands.store.target &&
         returned.type == IR_OP_VALUE && returned.value.id == load->result;
}

// Replace a self-call in return position with parameter updates and a jump to
// entry.
void optimizer_call_eliminate_tail_calls(Ctx* ctx, IrFunctionId fid) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  if (fid == ctx->ir.entrypoint)
    return;

  for (IrBlockId bid = 0; bid < fn->blocks.count; bid++) {
    IrBlock* block = &fn->blocks.data[bid];
    IrInstructionArray* instructions = &block->instructions;

    bool direct = block->terminator.type == IR_TERMINATOR_RETURN;

    size_t suffix = direct ? 1 : 2;

    if (instructions->count < suffix)
      continue;

    size_t last = instructions->count - suffix;
    IrInstruction call = instructions->data[last];
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Remove builtin functions from the IR altogether (they should now
    // be handled by lowering to allow for their optimalization, no?). Propagate
    // these changes to the relevant systems (codegen, optimizer)"
    // Changes: Treat every CALL as a user function call.
    if (call.type != IR_INST_CALL || call.operands.call.id != fid)
      continue;

    if (direct) {
      IrOperand result = block->terminator.value.return_value;

      if (fn->return_type != IR_UNIT &&
          (call.result == IR_INVALID_ID || result.type != IR_OP_VALUE ||
           result.value.id != call.result))
        continue;
    } else if (!returns_stored_call(fn, block, last, call.result))
      continue;

    // Call operands already hold the original values, so these stores can
    // update parameter slots in order even when two arguments swap slots.
    for (size_t a = 0; a < call.operands.call.arg_count; a++)
      optimizer_call_emit_argument_store(ctx, fid, bid, a,
                                         call.operands.call.args[a]);

    for (size_t i = 0; i < suffix; i++) {
      ir_free_instruction(&instructions->data[last]);
      array_remove(ctx, instructions, last);
    }

    ir_set_terminator(ctx, fid, bid, optimizer_call_jump_to(fn->entrypoint));
  }
}
